  for (const playerId of removedIds) room.players.delete(playerId);
  if (removedIds.has(room.turn.activePlayerId)) room.turn.activePlayerId = null;

  // Board snapshots may reference a removed hand owner, so they cannot remain safely undoable.
  room.undoStack = [];
